#!/bin/sh
# GENERATED by `gleam run -m generate` in drills/ - do not edit.
# Runs every Ruby solution variant against its harness:
#   ./verify_all.sh     (from drills/ruby)
# The report is the last line, a JSON object whose error is null and
# whose cases all passed.
cd "$(dirname "$0")" || exit 1
count=0
failures=0
while IFS='|' read -r module label stem; do
  [ -z "$stem" ] && continue
  count=$((count + 1))
  report=$(timeout -s KILL 10 ruby --disable-gems ".verify/$stem/run.rb" ".verify/$stem" 2>&1 | tail -n 1)
  [ -z "$report" ] && report='timed out'
  case "$report" in
    *'"error":null'*) ;;
    *) failures=$((failures + 1)); echo "FAIL $module [$label] $report"; continue ;;
  esac
  case "$report" in
    *'"cases":[]'*) failures=$((failures + 1)); echo "FAIL $module [$label] harness produced no cases" ;;
    *'"passed":false'*) failures=$((failures + 1)); echo "FAIL $module [$label] $report" ;;
  esac
done <<'VARIANTS'
nc01_contains_duplicate|Sorting|nc01_contains_duplicate__sorting
nc01_contains_duplicate|Hash Set|nc01_contains_duplicate
nc02_valid_anagram|Sorting|nc02_valid_anagram__sorting
nc02_valid_anagram|Count Map|nc02_valid_anagram
nc03_two_sum|Brute Force|nc03_two_sum__brute_force
nc03_two_sum|Hash Map|nc03_two_sum
nc04_group_anagrams|Sorted Key|nc04_group_anagrams__sorted_key
nc04_group_anagrams|Count Key|nc04_group_anagrams
nc05_top_k_frequent|Sorting|nc05_top_k_frequent__sorting
nc05_top_k_frequent|Bucket Sort|nc05_top_k_frequent
nc06_product_except_self|Brute Force|nc06_product_except_self__brute_force
nc06_product_except_self|Prefix & Suffix Products|nc06_product_except_self
nc07_longest_consecutive|Sorting|nc07_longest_consecutive__sorting
nc07_longest_consecutive|Hash Set|nc07_longest_consecutive
nc08_valid_palindrome|Nifty Python · Reverse|nc08_valid_palindrome__cleaned_reverse
nc08_valid_palindrome|Two Pointers|nc08_valid_palindrome
nc09_two_sum_sorted|Binary Search|nc09_two_sum_sorted__binary_search
nc09_two_sum_sorted|Two Pointers|nc09_two_sum_sorted
nc10_three_sum|Brute Force|nc10_three_sum__brute_force
nc10_three_sum|Sort + Two Pointers|nc10_three_sum
VARIANTS
echo "$count Ruby variants checked, $failures failures"
[ "$failures" -eq 0 ]
